#include <bits/stdc++.h>
using namespace std;

int main() {
	// your code goes here
    int t;
    cin >> t;
    
    while(t--) {
        int n;
        cin >> n;
        int m=n*3;
        
        vector<long long> arr(m),pref(m+1,0);
        
        for(int i = 0; i < m; i++) {
            cin >> arr[i];
        }
        
        sort(arr.rbegin(), arr.rend());
        
        long long ans = 0;
        
        for(int i = 0; i < m; i++) {
            pref[i+1]=pref[i]+arr[i];
        }
        for(int x=0 ;x<=n;x++){
            int maxY=n-x;
            int l=0,r=maxY;
            
            auto delta = [&](int y) -> long long {
                int k = 3 * n - 2 * x - y;
                
                return arr[x + 2 * y] + arr[x + 2 * y + 1] - 3LL * arr[k - 1];
            };
            
            while(l < r) {
                int mid = l +  (r - l) / 2;
                
                if(mid < maxY && delta(mid) >= 0) {
                    l = mid + 1;
                }
                else {
                    r = mid;
                }
            }
            
            int y = l;
            int k = 3 * n - 2 * x - y;
            
            long long curr = 2LL * pref[x] + pref[x + 2 * y] + 3LL * pref[k];
            
            ans = max(ans, curr);
        }
        cout << ans << '\n';
    }
}
